  SERVICE wikibase:box {
    ?item wdt:P625 ?coord .
    bd:serviceParam wikibase:cornerSouthWest "Point(18.69 42.4)"^^geo:wktLiteral .
    bd:serviceParam wikibase:cornerNorthEast "Point(18.79 42.47)"^^geo:wktLiteral .
  }
  ?item wdt:P31 ?type .
  OPTIONAL { ?item rdfs:label ?label . FILTER(LANG(?label) IN ("sr", "sr-el", "sh", "hr", "en", "de", "ru", "it")) }
